function renderResults(){const p=state.active;$('results').replaceChildren();const done=p&&p.next>=p.steps.length;$('continuePlan').hidden=!p||done;$('continuePlan').textContent=p?`Revisar e executar etapa ${p.next+1}`:'Voltar ao plano';$('resultTitle').textContent=done?'Entrega final e etapas':'Resultados por etapa';$('resultHint').textContent=done?'A última saída é a entrega final. Confira os critérios; o aplicativo não a valida automaticamente.':p?.results.length?'As saídas anteriores ficam recolhidas para facilitar a navegação.':'Nenhum resultado ainda. Aprove o plano e execute a primeira etapa.';for(const [i,r]of(p?.results||[]).entries()){const isFinal=done&&i===p.results.length-1;const details=node('details',undefined,'resultcard'+(isFinal?' final':''));details.open=i===p.results.length-1;details.append(node('summary',`${isFinal?'Entrega final':`Etapa ${i+1}`} · ${r.title}`),node('p',`Executor: ${r.executor} · ${r.model==='demo'?'Demonstração':r.metrics?.usage?`Uso informado: ${JSON.stringify(r.metrics.usage)}`:'Consumo não informado pelo provedor'}`,'metadata'));const copy=node('button','Copiar resultado','secondary');copy.onclick=async()=>{try{await navigator.clipboard.writeText(r.output);message('Resultado copiado.');}catch{message('Não foi possível copiar. Selecione o texto do resultado.');}};details.append(copy,listenButton(r.output),node('pre',r.output));$('results').append(details);}}
async function refresh(){const oldId=state?.project.id;state=await api('state');if(oldId!==state.project.id){$('task').value='';$('chatInput').value='';selectedStep=Math.min(state.active?.next||0,Math.max(0,(state.active?.steps.length||1)-1));dirty=false;}$('status').textContent=state.settings.demo?'DEMONSTRAÇÃO · SEM INFERÊNCIA':'MODO REAL · VIA OMNIROUTE';$('memory').textContent=`Apollo: ${state.memoryMB} MB de RAM · navegador, OmniRoute e modelos não incluídos · uma chamada por vez`;$('projectSelect').replaceChildren();for(const p of state.projects){const option=node('option',p.name);option.value=p.id;$('projectSelect').append(option);}$('projectSelect').value=state.project.id;$('chat').replaceChildren();for(const m of state.project.chat){const article=node('article',undefined,`chatmessage ${m.role}${m.error?' error':''}`);article.append(node('div',m.role==='user'?`Você${m.error?' · envio sem resposta':''}`:`Apollo · ${m.model}`,'who'),node('p',m.content));if(m.role==='assistant')article.append(listenButton(m.content));$('chat').append(article);}$('chat').scrollTop=$('chat').scrollHeight;$('demo').checked=state.settings.demo;for(const key of ['baseUrl','planner','worker','chatModel','asrEngine','ttsEngine'])$(key).value=state.settings[key];$('routes').value=state.settings.routes.map(r=>`${r.id} | ${r.label}`).join('\n');$('voicePreset').value=state.settings.voice; $('keyStatus').textContent=state.hasKey?'Chave disponível no processo; não exibida no navegador.':'Chave ausente. Use o lançador de integração para modo real.';$('history').replaceChildren();for(const e of state.history.slice().reverse()){const d=node('details');d.append(node('summary',`${new Date(e.at).toLocaleString('pt-BR')} · ${e.type==='plan'?'Plano':e.type==='chat'?'Conversa':'Resultado'}`));d.append(node('pre',e.output||e.task||'Uso e evento registrados; conteúdo no projeto correspondente.'));$('history').append(d);}renderPlan();renderResults();tab(view);controls();}
