 if(capture!==session||sequence!==captureSequence)return;
 const raw=await api('voice/transcribe',{audio,mime,durationMs});$('rawTranscript').textContent='Original: '+raw.text;
 if(capture!==session||sequence!==captureSequence)return;
 $('captureStatus').textContent='Corrigindo transcrição…';const clean=await api('voice/correct',{text:raw.text});$('cleanTranscript').textContent='Corrigida: '+clean.text;
 $('voiceUsage').textContent=(raw.asrEngine==='groq'?`Estimativa da transcrição: US$ ${raw.estimatedTranscriptionUSD.toFixed(6)}. `:'Transcrição local. ')+(clean.metrics?.usage?`Correção: ${JSON.stringify(clean.metrics.usage)}`:'Correção sem uso informado.');
 if(capture!==session||sequence!==captureSequence||state.project.id!==projectId)return;
 if($('chatInput').value.trim()){stopCapture('Envio pausado: há um rascunho digitado.');message('A fala corrigida está em Última transcrição e correção; o rascunho foi preservado.');return;}
 session.turns++;$('chatInput').value=clean.text;$('captureStatus').textContent='Enviando mensagem…';
