$('downloadSite').onclick=async()=>{if(!state.active)return;const p=state.active;$('downloadSite').disabled=true;try{const response=await fetch('/api/export/site',{method:'POST',headers:{'X-Apollo-Token':token,'Content-Type':'application/json'},body:JSON.stringify({projectId:state.project.id,id:p.id,version:p.version})});if(!response.ok){const error=await response.json();throw new Error(error.error);}const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='apollo-site.zip';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message('ZIP preparado. Confira os arquivos e o README.');}catch(e){message(e.message);}finally{controls();}};
function drawBrandGlobe(){const canvas=$('brandGlobe'),ctx=canvas.getContext('2d');const land=[[-18,36,15,37,40,15,30,-34,12,-35,-5,4],[-10,37,0,62,38,70,75,55,90,10,50,5,32,35],[108,-10,153,-10,155,-40,115,-35],[-82,12,-65,10,-34,-8,-45,-23,-70,-55,-80,-15]];const inside=(x,y,p)=>{let v=false;for(let i=0,j=p.length-2;i<p.length;j=i,i+=2){const xi=p[i],yi=p[i+1],xj=p[j],yj=p[j+1];if((yi>y)!==(yj>y)&&x<(xj-xi)*(y-yi)/(yj-yi)+xi)v=!v;}return v;};ctx.clearRect(0,0,240,240);for(let y=0;y<40;y++)for(let x=0;x<40;x++){const nx=(x-19.5)/19.5,ny=(y-19.5)/19.5,q=nx*nx+ny*ny;if(q>1)continue;const lat=Math.asin(-ny)*180/Math.PI,lon=Math.atan2(nx,Math.sqrt(1-q))*180/Math.PI+15,isLand=land.some(p=>inside(lon,lat,p));ctx.fillStyle=isLand?(lat>50||lat< -65?'#d4c89a':'#4a8c5c'):'#2d6a9f';ctx.fillRect(x*6,y*6,5,5);}}drawBrandGlobe();


